import{_ as o,o as r,c as t,a2 as a}from"./chunks/framework.DTwTvi8b.js";const u=JSON.parse('{"title":"0018 可选：流水线为需求新建 worktree 工作区","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0018-own-worktree-option.md","filePath":"reference/adr/0018-own-worktree-option.md","lastUpdated":null}'),i={name:"reference/adr/0018-own-worktree-option.md"};function n(d,e,s,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="_0018-可选-流水线为需求新建-worktree-工作区" tabindex="-1">0018 可选：流水线为需求新建 worktree 工作区 <a class="header-anchor" href="#_0018-可选-流水线为需求新建-worktree-工作区" aria-label="Permalink to &quot;0018 可选：流水线为需求新建 worktree 工作区&quot;">​</a></h1><ul><li>状态：已采纳（补充 <a href="./0001-step-agents-under-origin-chat">0001</a>、<a href="./0002-no-directory-switch-in-chat">0002</a>：两条的规则不变，增加一种由流水线放置步骤的方式）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>在项目主目录、主分支上发起的需求，原来只能请使用者自己在 Paseo 中新建 worktree 工作区、换到那里的对话重新开始，或者在主目录新建分支（主目录被占用几个小时）。对不熟悉 worktree 的使用者来说，第一种多了一次切换，第三种影响主目录。</p><p>Paseo 0.11 支持在指定的工作区中创建 agent，同时保持它是发起对话的子 agent（&quot;放置不改变归属&quot;），也能由 SDK 新建 worktree 工作区并执行 <code>paseo.json</code> 的准备脚本。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>启动时加 <code>--worktree</code>（<code>/req</code> 中的&quot;启动（自动新建工作区）&quot;）：流水线用 Paseo 从当前分支切出 <code>feature/&lt;功能目录名&gt;</code>，新建 worktree 工作区；把需求说明等文件移过去并在新分支上提交（原处未提交的副本删除，已提交的保留）；之后各步骤 agent 放在这个工作区中运行，仍然挂在发起的对话下。</li><li><strong>对话的工作目录不变</strong>（0002 不变）。对话里的查看进度、暂停、继续、验收命令照常在原目录执行，启动器会按状态文件中记录的来源目录找到新工作区；只允许从这个来源目录的对话操作。</li><li>发给对话的通知中，功能目录和报告写完整路径，因为它们不在对话的目录里。</li><li>只用于第一次启动；已经在原处运行过的需求不能中途改为新工作区。</li><li>默认仍然是原来的方式，这是一个可选项。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>主分支上发起的需求不再需要使用者手动建工作区；<code>paseo.json</code> 的准备脚本自动执行。对话 agent 需要用完整路径读写需求文件，<code>/req</code> 中已写明。新工作区的归档和清理仍由使用者在 Paseo 中决定。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0018-own-worktree-option.md">docs/adr/0018-own-worktree-option.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0018-own-worktree-option.md">在 GitHub 上编辑</a></p>',2)])])}const k=o(i,[["render",n]]);export{u as __pageData,k as default};
